/**
 * The Unicode property names and values regex-syntax 0.8.8 knows, which Codex 0.159.3's regex
 * crate looks a `\p{…}` class up in: its unicode_tables, Unicode 16.0.0, names only. Written by
 * g137.local/gen-unicode-names.mjs from the crate's source; do not edit by hand.
 */
/** A table written as `key:value` pairs, one string, which the formatter leaves on its line. */
function table(pairs: string): Record<string, string> {
  return Object.fromEntries(pairs.split(",").map((pair) => pair.split(":")));
}

